package org.apache.commons.math.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.linear.MatrixUtils;
import org.apache.commons.math.linear.RealMatrix;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CholeskyDecompositionImpl.getDeterminant().
 * The method calculates the determinant of the original matrix by squaring 
 * the diagonal elements of the L factor (since det(A) = det(L * L^T) = det(L)^2).
 */
public class CholeskyDecompositionImpl_getDeterminant_TriageGen1Test {

    @Test
    public void testGetDeterminant_IdentityMatrix() {
        // Identity matrix is symmetric and positive definite
        // L factor will be Identity, det(L) = 1, det(L)^2 = 1
        RealMatrix matrix = MatrixUtils.createRealIdentityMatrix(3);
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 1.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-12);
    }

    @Test
    public void testGetDeterminant_DiagonalMatrix() {
        // A = [4, 0; 0, 9], det(A) = 36
        // L = [2, 0; 0, 3], det(L) = 6, det(L)^2 = 36
        RealMatrix matrix = MatrixUtils.createRealMatrix(new double[][] {
            {4.0, 0.0},
            {0.0, 9.0}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 36.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-12);
    }

    @Test
    public void testGetDeterminant_FullMatrix() {
        // A = [4, 12, -16; 12, 37, -43; -16, -43, 98]
        // This is a known positive definite matrix
        // L = [2, 0, 0; 6, 1, 0; -8, 5, 3]
        // det(L) = 2 * 1 * 3 = 6
        // det(A) = 6^2 = 36
        RealMatrix matrix = MatrixUtils.createRealMatrix(new double[][] {
            {4.0, 12.0, -16.0},
            {12.0, 37.0, -43.0},
            {-16.0, -43.0, 98.0}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 36.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-12);
    }

    @Test
    public void testGetDeterminant_SingleElement() {
        // A = [25], det(A) = 25
        // L = [5], det(L)^2 = 25
        RealMatrix matrix = MatrixUtils.createRealMatrix(new double[][] {
            {25.0}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 25.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-12);
    }

    @Test
    public void testGetDeterminant_SmallValues() {
        // Test precision with small values
        double val = 0.001;
        RealMatrix matrix = MatrixUtils.createRealMatrix(new double[][] {
            {val * val, 0.0},
            {0.0, val * val}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        // det(A) = (val^2)^2 = val^4 = 1e-12
        double expected = Math.pow(val, 4);
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-18);
    }
}
